        CollectedType::IndexedAccess { .. } | CollectedType::Conditional { .. } => {
            let (reduced, reduced_file) = reduce(obj, file, ctx, depth + 1)?;
            member(&reduced, key, &reduced_file, ctx, depth + 1)
        }
        _ => None,
    }
}

